abstract class LayerObject(protected val id: Long) {   // the layer's declared type
    var version: Int = 0
        protected set
    fun touch() { version++ }                          // shared, not overridable
    abstract fun describe(): String                    // required per member
}
class User(id: Long, val email: String) : LayerObject(id) {
    override fun describe() = "user $id"
}
